window.CHUJI_DATA_6 = [{"l": 351, "lt": "Lesson 51 My Girlfriend 我的女友", "i": 1, "type": "reading", "en": "My girlfriend always complains.", "zh": "我的女友老爱发牢骚。", "audio": "chuji_l51_01.mp3", "localAudio": "audio_chunks/chuji_l51_01.mp3", "b64": "", "src": "chuji"}, {"l": 351, "lt": "Lesson 51 My Girlfriend 我的女友", "i": 2, "type": "reading", "en": "According to her, I should be more ambitious.", "zh": "根据她的说法，我应当更有进取心。", "audio": "chuji_l51_02.mp3", "localAudio": "audio_chunks/chuji_l51_02.mp3", "b64": "", "src": "chuji"}, {"l": 351, "lt": "Lesson 51 My Girlfriend 我的女友", "i": 3, "type": "reading", "en": "I should work harder and earn more money.", "zh": "我应当更卖力地工作，挣更多的钱。", "audio": "chuji_l51_03.mp3", "localAudio": "audio_chunks/chuji_l51_03.mp3", "b64": "", "src": "chuji"}, {"l": 351, "lt": "Lesson 51 My Girlfriend 我的女友", "i": 4, "type": "reading", "en": "She also thinks I should live in a bigger and nicer apartment.", "zh": "她也认为我应当住更大更好的公寓。", "audio": "chuji_l51_04.mp3", "localAudio": "audio_chunks/chuji_l51_04.mp3", "b64": "", "src": "chuji"}, {"l": 351, "lt": "Lesson 51 My Girlfriend 我的女友", "i": 5, "type": "reading", "en": "In a way, she's right.", "zh": "就某方面来说，她的话是对的。", "audio": "chuji_l51_05.mp3", "localAudio": "audio_chunks/chuji_l51_05.mp3", "b64": "", "src": "chuji"}, {"l": 351, "lt": "Lesson 51 My Girlfriend 我的女友", "i": 6, "type": "reading", "en": "However, she should be more considerate and less critical.", "zh": "不过，她也应当多体谅少批评。", "audio": "chuji_l51_06.mp3", "localAudio": "audio_chunks/chuji_l51_06.mp3", "b64": "", "src": "chuji"}, {"l": 351, "lt": "Lesson 51 My Girlfriend 我的女友", "i": 7, "type": "reading", "en": "After all, I am trying my best.", "zh": "毕竟，我正尽力而为。", "audio": "chuji_l51_07.mp3", "localAudio": "audio_chunks/chuji_l51_07.mp3", "b64": "", "src": "chuji"}, {"l": 351, "lt": "Lesson 51 My Girlfriend 我的女友", "i": 8, "type": "reading", "en": "Besides, money isn't everything.", "zh": "而且，金钱并非万能呀。", "audio": "chuji_l51_08.mp3", "localAudio": "audio_chunks/chuji_l51_08.mp3", "b64": "", "src": "chuji"}, {"l": 352, "lt": "Lesson 52 Sam's OK 小三子不错", "i": 1, "type": "dialog", "en": "Do you like Ray or Sam?", "zh": "你喜欢小雷还是小三子？", "audio": "chuji_l52_01.mp3", "localAudio": "audio_chunks/chuji_l52_01.mp3", "b64": "", "src": "chuji", "speaker": "Father", "note": "说话人: Father"}, {"l": 352, "lt": "Lesson 52 Sam's OK 小三子不错", "i": 2, "type": "dialog", "en": "I like Ray.", "zh": "我喜欢小雷。", "audio": "chuji_l52_02.mp3", "localAudio": "audio_chunks/chuji_l52_02.mp3", "b64": "", "src": "chuji", "speaker": "Daughter", "note": "说话人: Daughter"}, {"l": 352, "lt": "Lesson 52 Sam's OK 小三子不错", "i": 3, "type": "dialog", "en": "Why?", "zh": "为什么？", "audio": "chuji_l52_03.mp3", "localAudio": "audio_chunks/chuji_l52_03.mp3", "b64": "", "src": "chuji", "speaker": "Father", "note": "说话人: Father"}, {"l": 352, "lt": "Lesson 52 Sam's OK 小三子不错", "i": 4, "type": "dialog", "en": "Sam's OK, but Ray's taller, cuter and more interesting. What about you?", "zh": "小三子固然不错，但小雷个儿较高、较可爱、也较风趣。您觉得呢？", "audio": "chuji_l52_04.mp3", "localAudio": "audio_chunks/chuji_l52_04.mp3", "b64": "", "src": "chuji", "speaker": "Daughter", "note": "说话人: Daughter"}, {"l": 352, "lt": "Lesson 52 Sam's OK 小三子不错", "i": 5, "type": "dialog", "en": "I like Sam better.", "zh": "我比较喜欢小三子。", "audio": "chuji_l52_05.mp3", "localAudio": "audio_chunks/chuji_l52_05.mp3", "b64": "", "src": "chuji", "speaker": "Father", "note": "说话人: Father"}, {"l": 352, "lt": "Lesson 52 Sam's OK 小三子不错", "i": 6, "type": "dialog", "en": "Why?", "zh": "为什么？", "audio": "chuji_l52_06.mp3", "localAudio": "audio_chunks/chuji_l52_06.mp3", "b64": "", "src": "chuji", "speaker": "Daughter", "note": "说话人: Daughter"}, {"l": 352, "lt": "Lesson 52 Sam's OK 小三子不错", "i": 7, "type": "dialog", "en": "He's less proud. Besides, he's richer!", "zh": "他比较不骄傲。而且，他比较有钱！", "audio": "chuji_l52_07.mp3", "localAudio": "audio_chunks/chuji_l52_07.mp3", "b64": "", "src": "chuji", "speaker": "Father", "note": "说话人: Father"}, {"l": 353, "lt": "Lesson 53 Country Life 乡间生活", "i": 1, "type": "reading", "en": "My parents prefer to live in the country.", "zh": "我爸妈比较喜欢住在乡下。", "audio": "chuji_l53_01.mp3", "localAudio": "audio_chunks/chuji_l53_01.mp3", "b64": "", "src": "chuji"}, {"l": 353, "lt": "Lesson 53 Country Life 乡间生活", "i": 2, "type": "reading", "en": "The streets there are cleaner.", "zh": "那儿的街道比较干净。", "audio": "chuji_l53_02.mp3", "localAudio": "audio_chunks/chuji_l53_02.mp3", "b64": "", "src": "chuji"}, {"l": 353, "lt": "Lesson 53 Country Life 乡间生活", "i": 3, "type": "reading", "en": "The air is fresher and the people are nicer and friendlier.", "zh": "空气较新鲜，人也比较好、比较友善。", "audio": "chuji_l53_03.mp3", "localAudio": "audio_chunks/chuji_l53_03.mp3", "b64": "", "src": "chuji"}, {"l": 353, "lt": "Lesson 53 Country Life 乡间生活", "i": 4, "type": "reading", "en": "Besides, it is busier and noisier in the city.", "zh": "而且，都市里比较忙碌，也比较吵闹。", "audio": "chuji_l53_04.mp3", "localAudio": "audio_chunks/chuji_l53_04.mp3", "b64": "", "src": "chuji"}, {"l": 353, "lt": "Lesson 53 Country Life 乡间生活", "i": 5, "type": "reading", "en": "But above all, it is safer to live in the country.", "zh": "但最重要的是，住在乡下比较安全。", "audio": "chuji_l53_05.mp3", "localAudio": "audio_chunks/chuji_l53_05.mp3", "b64": "", "src": "chuji"}, {"l": 353, "lt": "Lesson 53 Country Life 乡间生活", "i": 6, "type": "reading", "en": "My parents believe in the saying, \"Safety first.\"", "zh": "我父母深信这句谚语：“安全至上。”", "audio": "chuji_l53_06.mp3", "localAudio": "audio_chunks/chuji_l53_06.mp3", "b64": "", "src": "chuji"}, {"l": 354, "lt": "Lesson 54 I Like Brighter Colors 我喜欢较明亮的颜色", "i": 1, "type": "dialog", "en": "Do you like my new dress, Mike?", "zh": "迈克，你喜欢我这件新的女式套装吗？", "audio": "chuji_l54_01.mp3", "localAudio": "audio_chunks/chuji_l54_01.mp3", "b64": "", "src": "chuji", "speaker": "Tracy", "note": "说话人: Tracy"}, {"l": 354, "lt": "Lesson 54 I Like Brighter Colors 我喜欢较明亮的颜色", "i": 2, "type": "dialog", "en": "Frankly, I like brighter colors better. They make you look younger.", "zh": "坦白说，我比较喜欢明亮一点的颜色。它们会使你看起来年轻些。", "audio": "chuji_l54_02.mp3", "localAudio": "audio_chunks/chuji_l54_02.mp3", "b64": "", "src": "chuji", "speaker": "Mike", "note": "说话人: Mike"}, {"l": 354, "lt": "Lesson 54 I Like Brighter Colors 我喜欢较明亮的颜色", "i": 3, "type": "dialog", "en": "Do darker colors make me look older?", "zh": "深一点的颜色会使我看起来年纪大一点啰？", "audio": "chuji_l54_03.mp3", "localAudio": "audio_chunks/chuji_l54_03.mp3", "b64": "", "src": "chuji", "speaker": "Tracy", "note": "说话人: Tracy"}, {"l": 354, "lt": "Lesson 54 I Like Brighter Colors 我喜欢较明亮的颜色", "i": 4, "type": "dialog", "en": "Well...yes.", "zh": "嗯……是的。", "audio": "chuji_l54_04.mp3", "localAudio": "audio_chunks/chuji_l54_04.mp3", "b64": "", "src": "chuji", "speaker": "Mike", "note": "说话人: Mike"}, {"l": 354, "lt": "Lesson 54 I Like Brighter Colors 我喜欢较明亮的颜色", "i": 5, "type": "dialog", "en": "Then, buy me another dress.", "zh": "那么，给我另外买一套吧！", "audio": "chuji_l54_05.mp3", "localAudio": "audio_chunks/chuji_l54_05.mp3", "b64": "", "src": "chuji", "speaker": "Tracy", "note": "说话人: Tracy"}, {"l": 355, "lt": "Lesson 55 More Is Not Always Better 多未必佳", "i": 1, "type": "reading", "en": "Some people have more money than others.", "zh": "有些人比别人有钱。", "audio": "chuji_l55_01.mp3", "localAudio": "audio_chunks/chuji_l55_01.mp3", "b64": "", "src": "chuji"}, {"l": 355, "lt": "Lesson 55 More Is Not Always Better 多未必佳", "i": 2, "type": "reading", "en": "However, they're not necessarily happier.", "zh": "不过，他们未必就比较快乐。", "audio": "chuji_l55_02.mp3", "localAudio": "audio_chunks/chuji_l55_02.mp3", "b64": "", "src": "chuji"}, {"l": 355, "lt": "Lesson 55 More Is Not Always Better 多未必佳", "i": 3, "type": "reading", "en": "On the other hand, some people are as poor as church mice, but they are happy.", "zh": "另一方面，有些人一贫如洗，但他们却很快乐。", "audio": "chuji_l55_03.mp3", "localAudio": "audio_chunks/chuji_l55_03.mp3", "b64": "", "src": "chuji"}, {"l": 355, "lt": "Lesson 55 More Is Not Always Better 多未必佳", "i": 4, "type": "reading", "en": "In a way, these poor people are as rich as kings.", "zh": "从某种角度来看，这些穷人却像国王一样富有。", "audio": "chuji_l55_04.mp3", "localAudio": "audio_chunks/chuji_l55_04.mp3", "b64": "", "src": "chuji"}, {"l": 355, "lt": "Lesson 55 More Is Not Always Better 多未必佳", "i": 5, "type": "reading", "en": "Therefore, I always remember my father's words, \"More is not always better.\"", "zh": "因此，我始终记得父亲的话：“多未必佳。”", "audio": "chuji_l55_05.mp3", "localAudio": "audio_chunks/chuji_l55_05.mp3", "b64": "", "src": "chuji"}, {"l": 356, "lt": "Lesson 56 I Want the Cheaper One 我要买那只便宜的手表", "i": 1, "type": "dialog", "en": "Why is this watch more expensive than that one?", "zh": "这只手表为什么比那只贵？", "audio": "chuji_l56_01.mp3", "localAudio": "audio_chunks/chuji_l56_01.mp3", "b64": "", "src": "chuji", "speaker": "Customer", "note": "说话人: Customer"}, {"l": 356, "lt": "Lesson 56 I Want the Cheaper One 我要买那只便宜的手表", "i": 2, "type": "dialog", "en": "Because its brand name is more famous.", "zh": "因为它的牌子比较出名。", "audio": "chuji_l56_02.mp3", "localAudio": "audio_chunks/chuji_l56_02.mp3", "b64": "", "src": "chuji", "speaker": "Salesgirl", "note": "说话人: Salesgirl"}, {"l": 356, "lt": "Lesson 56 I Want the Cheaper One 我要买那只便宜的手表", "i": 3, "type": "dialog", "en": "Is it more reliable?", "zh": "它比较可靠吗？", "audio": "chuji_l56_03.mp3", "localAudio": "audio_chunks/chuji_l56_03.mp3", "b64": "", "src": "chuji", "speaker": "Customer", "note": "说话人: Customer"}, {"l": 356, "lt": "Lesson 56 I Want the Cheaper One 我要买那只便宜的手表", "i": 4, "type": "dialog", "en": "No. Not really.", "zh": "不。不见得。", "audio": "chuji_l56_04.mp3", "localAudio": "audio_chunks/chuji_l56_04.mp3", "b64": "", "src": "chuji", "speaker": "Salesgirl", "note": "说话人: Salesgirl"}, {"l": 356, "lt": "Lesson 56 I Want the Cheaper One 我要买那只便宜的手表", "i": 5, "type": "dialog", "en": "Then, I want the cheaper one.", "zh": "那么，我要买那只便宜的手表。", "audio": "chuji_l56_05.mp3", "localAudio": "audio_chunks/chuji_l56_05.mp3", "b64": "", "src": "chuji", "speaker": "Customer", "note": "说话人: Customer"}, {"l": 357, "lt": "Lesson 57 The Elephant and the Whale 大象与鲸鱼", "i": 1, "type": "reading", "en": "The biggest and strongest animal on land is the elephant.", "zh": "陆地上最大、最强壮的动物就是大象。", "audio": "chuji_l57_01.mp3", "localAudio": "audio_chunks/chuji_l57_01.mp3", "b64": "", "src": "chuji"}, {"l": 357, "lt": "Lesson 57 The Elephant and the Whale 大象与鲸鱼", "i": 2, "type": "reading", "en": "The largest and heaviest animal in the sea is the whale.", "zh": "海中最大、最重的动物则是鲸鱼。", "audio": "chuji_l57_02.mp3", "localAudio": "audio_chunks/chuji_l57_02.mp3", "b64": "", "src": "chuji"}, {"l": 357, "lt": "Lesson 57 The Elephant and the Whale 大象与鲸鱼", "i": 3, "type": "reading", "en": "It's also the biggest eater in the world.", "zh": "它也是世界上食量最大的动物。", "audio": "chuji_l57_03.mp3", "localAudio": "audio_chunks/chuji_l57_03.mp3", "b64": "", "src": "chuji"}, {"l": 357, "lt": "Lesson 57 The Elephant and the Whale 大象与鲸鱼", "i": 4, "type": "reading", "en": "It eats a ton of food a day.", "zh": "它每天要吃一吨的食物。", "audio": "chuji_l57_04.mp3", "localAudio": "audio_chunks/chuji_l57_04.mp3", "b64": "", "src": "chuji"}, {"l": 357, "lt": "Lesson 57 The Elephant and the Whale 大象与鲸鱼", "i": 5, "type": "reading", "en": "It looks like a fish, but it is really a mammal.", "zh": "它看起来像鱼，但它实际上是哺乳动物。", "audio": "chuji_l57_05.mp3", "localAudio": "audio_chunks/chuji_l57_05.mp3", "b64": "", "src": "chuji"}, {"l": 357, "lt": "Lesson 57 The Elephant and the Whale 大象与鲸鱼", "i": 6, "type": "reading", "en": "Although the elephant and the whale are both mammals, they are indeed very different.", "zh": "虽然大象和鲸鱼都是哺乳动物，它们却大不相同。", "audio": "chuji_l57_06.mp3", "localAudio": "audio_chunks/chuji_l57_06.mp3", "b64": "", "src": "chuji"}, {"l": 358, "lt": "Lesson 58 The Smartest Teacher 最聪明的老师", "i": 1, "type": "dialog", "en": "Which country is the biggest in the world?", "zh": "世界上哪个国家最大？", "audio": "chuji_l58_01.mp3", "localAudio": "audio_chunks/chuji_l58_01.mp3", "b64": "", "src": "chuji", "speaker": "Teacher", "note": "说话人: Teacher"}, {"l": 358, "lt": "Lesson 58 The Smartest Teacher 最聪明的老师", "i": 2, "type": "dialog", "en": "Russia.", "zh": "俄罗斯。", "audio": "chuji_l58_02.mp3", "localAudio": "audio_chunks/chuji_l58_02.mp3", "b64": "", "src": "chuji", "speaker": "Student", "note": "说话人: Student"}, {"l": 358, "lt": "Lesson 58 The Smartest Teacher 最聪明的老师", "i": 3, "type": "dialog", "en": "Which country has the most people in the world?", "zh": "世界上哪个国家有最多的人？", "audio": "chuji_l58_03.mp3", "localAudio": "audio_chunks/chuji_l58_03.mp3", "b64": "", "src": "chuji", "speaker": "Teacher", "note": "说话人: Teacher"}, {"l": 358, "lt": "Lesson 58 The Smartest Teacher 最聪明的老师", "i": 4, "type": "dialog", "en": "China.", "zh": "中国。", "audio": "chuji_l58_04.mp3", "localAudio": "audio_chunks/chuji_l58_04.mp3", "b64": "", "src": "chuji", "speaker": "Student", "note": "说话人: Student"}, {"l": 358, "lt": "Lesson 58 The Smartest Teacher 最聪明的老师", "i": 5, "type": "dialog", "en": "Who is the smartest teacher in the school?", "zh": "本校中哪一位老师最聪明？", "audio": "chuji_l58_05.mp3", "localAudio": "audio_chunks/chuji_l58_05.mp3", "b64": "", "src": "chuji", "speaker": "Teacher", "note": "说话人: Teacher"}, {"l": 358, "lt": "Lesson 58 The Smartest Teacher 最聪明的老师", "i": 6, "type": "dialog", "en": "But...you are the only teacher in the school.", "zh": "但是……你是本校唯一的老师啊。", "audio": "chuji_l58_06.mp3", "localAudio": "audio_chunks/chuji_l58_06.mp3", "b64": "", "src": "chuji", "speaker": "Student", "note": "说话人: Student"}, {"l": 358, "lt": "Lesson 58 The Smartest Teacher 最聪明的老师", "i": 7, "type": "dialog", "en": "I know.", "zh": "我知道。", "audio": "chuji_l58_07.mp3", "localAudio": "audio_chunks/chuji_l58_07.mp3", "b64": "", "src": "chuji", "speaker": "Teacher", "note": "说话人: Teacher"}, {"l": 359, "lt": "Lesson 59 My Best Friend 我最好的朋友", "i": 1, "type": "reading", "en": "My best friend is the most thoughtful person in the world.", "zh": "我最好的朋友是世界上最体贴的人。", "audio": "chuji_l59_01.mp3", "localAudio": "audio_chunks/chuji_l59_01.mp3", "b64": "", "src": "chuji"}, {"l": 359, "lt": "Lesson 59 My Best Friend 我最好的朋友", "i": 2, "type": "reading", "en": "When I'm sad, he is the most sympathetic.", "zh": "当我难过时，他最富有同情心了。", "audio": "chuji_l59_02.mp3", "localAudio": "audio_chunks/chuji_l59_02.mp3", "b64": "", "src": "chuji"}, {"l": 359, "lt": "Lesson 59 My Best Friend 我最好的朋友", "i": 3, "type": "reading", "en": "When I'm sick, he is the most concerned.", "zh": "我生病时，他最为关切。", "audio": "chuji_l59_03.mp3", "localAudio": "audio_chunks/chuji_l59_03.mp3", "b64": "", "src": "chuji"}, {"l": 359, "lt": "Lesson 59 My Best Friend 我最好的朋友", "i": 4, "type": "reading", "en": "When I'm in trouble, he is the most helpful.", "zh": "我有困难时，他最帮我了。", "audio": "chuji_l59_04.mp3", "localAudio": "audio_chunks/chuji_l59_04.mp3", "b64": "", "src": "chuji"}, {"l": 359, "lt": "Lesson 59 My Best Friend 我最好的朋友", "i": 5, "type": "reading", "en": "In fact, he is the most dependable person in the world.", "zh": "事实上，他是世界上最值得信赖的人。", "audio": "chuji_l59_05.mp3", "localAudio": "audio_chunks/chuji_l59_05.mp3", "b64": "", "src": "chuji"}, {"l": 359, "lt": "Lesson 59 My Best Friend 我最好的朋友", "i": 6, "type": "reading", "en": "He is the closest person to me.", "zh": "他是我最亲近的人。", "audio": "chuji_l59_06.mp3", "localAudio": "audio_chunks/chuji_l59_06.mp3", "b64": "", "src": "chuji"}, {"l": 359, "lt": "Lesson 59 My Best Friend 我最好的朋友", "i": 7, "type": "reading", "en": "He is my father.", "zh": "他就是我父亲。", "audio": "chuji_l59_07.mp3", "localAudio": "audio_chunks/chuji_l59_07.mp3", "b64": "", "src": "chuji"}, {"l": 360, "lt": "Lesson 60 The Longest River in the World 世界上最长的河流", "i": 1, "type": "dialog", "en": "Which is the longest river in the world?", "zh": "世界上最长的河流是哪一条？", "audio": "chuji_l60_01.mp3", "localAudio": "audio_chunks/chuji_l60_01.mp3", "b64": "", "src": "chuji", "speaker": "Teacher", "note": "说话人: Teacher"}, {"l": 360, "lt": "Lesson 60 The Longest River in the World 世界上最长的河流", "i": 2, "type": "dialog", "en": "The Nile.", "zh": "尼罗河。", "audio": "chuji_l60_02.mp3", "localAudio": "audio_chunks/chuji_l60_02.mp3", "b64": "", "src": "chuji", "speaker": "Student", "note": "说话人: Student"}, {"l": 360, "lt": "Lesson 60 The Longest River in the World 世界上最长的河流", "i": 3, "type": "dialog", "en": "Which is the biggest ocean in the world?", "zh": "世界上最大的海洋是哪一个？", "audio": "chuji_l60_03.mp3", "localAudio": "audio_chunks/chuji_l60_03.mp3", "b64": "", "src": "chuji", "speaker": "Teacher", "note": "说话人: Teacher"}, {"l": 360, "lt": "Lesson 60 The Longest River in the World 世界上最长的河流", "i": 4, "type": "dialog", "en": "The Pacific Ocean.", "zh": "太平洋。", "audio": "chuji_l60_04.mp3", "localAudio": "audio_chunks/chuji_l60_04.mp3", "b64": "", "src": "chuji", "speaker": "Student", "note": "说话人: Student"}, {"l": 360, "lt": "Lesson 60 The Longest River in the World 世界上最长的河流", "i": 5, "type": "dialog", "en": "Which is the best school in the village?", "zh": "本村最好的学校是哪一所？", "audio": "chuji_l60_05.mp3", "localAudio": "audio_chunks/chuji_l60_05.mp3", "b64": "", "src": "chuji", "speaker": "Teacher", "note": "说话人: Teacher"}, {"l": 360, "lt": "Lesson 60 The Longest River in the World 世界上最长的河流", "i": 6, "type": "dialog", "en": "But...this is the only school in the village, sir.", "zh": "但是……老师，本校是村里唯一的学校啊。", "audio": "chuji_l60_06.mp3", "localAudio": "audio_chunks/chuji_l60_06.mp3", "b64": "", "src": "chuji", "speaker": "Student", "note": "说话人: Student"}, {"l": 360, "lt": "Lesson 60 The Longest River in the World 世界上最长的河流", "i": 7, "type": "dialog", "en": "I know.", "zh": "我知道。", "audio": "chuji_l60_07.mp3", "localAudio": "audio_chunks/chuji_l60_07.mp3", "b64": "", "src": "chuji", "speaker": "Teacher", "note": "说话人: Teacher"}];